        def helper():
            pass

        class TestNosetest:
            def test_nose(self):
                pass
            test_nose.__test__ = True

        class TestNo:
            def test_disabled(self):
                pass
            test_disabled.__test__ = False

        def not_a_test():
            pass
        not_a_test.someattr = True  # not __test__ = True
        """
    )
    items = testdir.getitems("test_istestfunction.py")
    item_names = [item.name for item in items]
    # test_static.test_static should be collected as a test (Path 1)
    # test_normal is collected (Path 2)
    # test_nose is collected due to __test__ = True (Path 2)
    # test_disabled and not_a_test are not collected (Path 3)
    assert 'test_static' in item_names
    assert 'test_normal' in item_names
    assert 'test_nose' in item_names
    assert 'test_disabled' not in item_names
    assert 'not_a_test' not in item_names
