def test_pycollector_collect(testdir):
    """Test PyCollector.collect with various scenarios to cover execution paths."""
    # Path 1: __test__ = False
    testdir.makepyfile(test_nocollect="""
        class TestNoTest:
            __test__ = False
            def test_method(self):
                pass
    """)
    reprec = testdir.inline_run("test_nocollect.py")
    reprec.assertoutcome(passed=0, failed=0, skipped=0, errors=0)

    # Path 2-10: Collection from __dict__ and base classes
    testdir.makepyfile(test_collect="""
        class Base:
            def test_base(self):
                pass

        class TestDerived(Base):
            def test_derived(self):
                pass

        class TestDuplicates:
            def test_one(self):
                pass
            def test_one(self):  # Duplicate in same class
                pass

        class TestNonTest:
            def helper(self):  # Not a test method
                pass
            def test_valid(self):
                pass

        class TestMixed:
            def test_first(self):
                pass
            def test_second(self):
                pass
    """)
    reprec = testdir.inline_run()
    reprec.assertoutcome(passed=5)  # test_base, test_derived, test_one, test_valid, test_{first,second}

    # Check duplicate handling (Path 6)
    result = testdir.runpytest("test_collect.py::TestDuplicates", "-v")
    result.stdout.fnmatch_lines([
        "*test_one PASSED*",
        "*1 passed*"
    ])

    # Check non-test method not collected (Path 5)
    result = testdir.runpytest("test_collect.py::TestNonTest", "-v")
    result.stdout.fnmatch_lines([
        "*test_valid PASSED*",
        "*1 passed*"
    ])
    assert "helper" not in result.stdout.str()

    # Path 3: Base class collection
    result = testdir.runpytest("test_collect.py::TestDerived", "-v")
    result.stdout.fnmatch_lines([
        "*test_base PASSED*",
        "*test_derived PASSED*",
        "*2 passed*"
    ])
