            (
                ["arg1", "arg2"],
                True,
                {
                    "arg1": [MockFixtureDef("session")],
                    "arg2": [MockFixtureDef("module")],
                },
                "session",
            ),
            # Path 8: indirect True, fixtures have 'class' and 'function'
            (
                ["arg1", "arg2"],
                True,
                {
                    "arg1": [MockFixtureDef("class")],
                    "arg2": [MockFixtureDef("function")],
                },
                "function",
            ),
            # Path 6: indirect True, no fixtures → used_scopes empty
            (
                ["arg1", "arg2"],
                True,
                {},
                "function",
            ),
        ],
    )
    def test_find_parametrized_scope(self, argnames, indirect, arg2fixturedefs, expected_scope):
