def test_RandomDomain_printing():
    from sympy.stats.rv import RandomDomain
    from sympy import symbols, Interval, sstr

    x = symbols('x')

    # Path 1: Domain with 'as_boolean' attribute
    class DomainPath1(RandomDomain):
        @property
        def symbols(self):
            return x
        def as_boolean(self):
            return x > 0
    d1 = DomainPath1()
    assert sstr(d1) == 'Domain: x > 0'

    # Path 2: Domain without 'as_boolean' but with 'set' attribute
    class DomainPath2(RandomDomain):
        @property
        def symbols(self):
            return x
        @property
        def set(self):
            return Interval(0, 1)
    d2 = DomainPath2()
    assert sstr(d2) == 'Domain: x in Interval(0, 1)'

    # Path 3: Domain without 'as_boolean' or 'set' attributes
    class DomainPath3(RandomDomain):
        @property
        def symbols(self):
            return x
    d3 = DomainPath3()
    assert sstr(d3) == 'Domain on x'
