from django.core.exceptions import ImproperlyConfigured
from django.test import TestCase
from django.db import models
from django.contrib import admin
from django.contrib.admin.sites import AlreadyRegistered

class AdminSiteRegisterTests(TestCase):
    def setUp(self):
        self.site = admin.AdminSite()

    def test_register_abstract_model_raises_exception(self):
        """Path 1: Registering an abstract model raises ImproperlyConfigured."""
        class TestModel(models.Model):
            class Meta:
                abstract = True
        with self.assertRaisesMessage(ImproperlyConfigured, 'abstract'):
            self.site.register(TestModel)

    def test_register_already_registered_default_admin(self):
        """Path 2: Registering an already registered model with default admin."""
        self.site.register(User)
        with self.assertRaisesMessage(AlreadyRegistered, "in app 'auth'"):
            self.site.register(User)

    def test_register_already_registered_custom_admin(self):
        """Path 3: Registering an already registered model with custom admin."""
        class CustomAdmin(admin.ModelAdmin):
            pass
        self.site.register(User, CustomAdmin)
        with self.assertRaisesMessage(AlreadyRegistered, "with CustomAdmin"):
            self.site.register(User)

    def test_register_concrete_and_abstract_model(self):
        """Path 4: Registering non-abstract then abstract model in one call."""
        class ConcreteModel(models.Model):
            pass
        class AbstractModel(models.Model):
            class Meta:
                abstract = True
        with self.assertRaisesMessage(ImproperlyConfigured, 'abstract'):
            self.site.register([ConcreteModel, AbstractModel], list_display=['id'])
        self.assertIn(ConcreteModel, self.site._registry)

    def test_register_with_options_creates_new_admin_class(self):
        """Path 8: Registering with options creates dynamic admin class."""
        self.site.register(User, list_display=['id'])
        admin_instance = self.site._registry[User]
        self.assertEqual(admin_instance.list_display, ['id'])
        self.assertTrue(hasattr(admin_instance, 'list_display'))

    def test_register_multiple_models_with_options(self):
        """Path 7: Registering multiple models with options in one call."""
        class ModelA(models.Model):
            pass
        class ModelB(models.Model):
            pass
        self.site.register([ModelA, ModelB], list_filter=['id'])
        self.assertTrue(hasattr(self.site._registry[ModelA], 'list_filter'))
        self.assertTrue(hasattr(self.site._registry[ModelB], 'list_filter'))

    def test_register_swapped_model_skips_registration(self):
        """Path 9: Registering a swapped model skips registration."""
        class SwappedModel(models.Model):
            class Meta:
                swapped = True
        self.site.register(SwappedModel)
        self.assertNotIn(SwappedModel, self.site._registry)
