class TestPytestPyfuncCall:
    @pytest.mark.parametrize("is_async, has_await, awas_calls", [
        (True, True, 2),   # Path 1: async function and awaitable result
        (True, False, 1),  # Path 2: async function, no await
        (False, True, 1),  # Path 3: non-async but awaitable result
        (False, False, 0),  # Path4: normal function
    ])
    def test_pytest_pyfunc_call(self, monkeypatch, is_async, has_await, awas_calls):
        # Mock async_warn_and_skip to count calls
        mock_awas = Mock()
        monkeypatch.setattr('pytest._pytest.python.async_warn_and_skip', mock_awas)
        # Mock is_async_function
        monkeypatch.setattr('pytest._pytest.python.is_async_function', lambda x: is_async)

        # Create mock pyfuncitem
        class MockPyfuncItem:
            def __init__(self):
                self.nodeid = "mock_nodeid"
                self.funcargs = {}
                self._fixtureinfo = Mock()
                self._fixtureinfo.argnames = []

            def mock_testfunction(self, **kwargs):
                class Result:
                    def __init__(self, has_await):
                        self.has_await = has_await
                    def __await__(self):
                        if self.has_await:
                            return iter([])
                        raise AttributeError
                    __aiter__ = __await__
                return Result(has_await)

            obj = property(mock_testfunction)

        item = MockPyfuncItem()

        # Run the function under test
        pytest_pyfunc_call(item)
        # Assert the correct number of calls to async_warn_and_skip
        assert mock_awas.call_count == awas_calls
