@isolate_apps('check_framework', attr_name='apps')
@override_system_checks([checks.model_checks.check_all_models])
class PropertyNameRelatedFieldAccessorClashTests(SimpleTestCase):
    def test_property_name_related_field_accessor_clashes(self):
        class ClashModel(models.Model):
            # Related field 'rel' with attname 'rel_id' (column name)
            rel = models.ForeignKey('self', on_delete=models.CASCADE)
            # Property 'rel_id' clashes with the related field's attname (column name)
            @property
            def rel_id(self):
                return 1

            class Meta:
                app_label = 'check_framework'

        expected_error = checks.Error(
            "The property 'rel_id' clashes with a related field accessor.",
            obj=ClashModel,
            id='models.E025',
        )
        self.assertEqual(ClashModel.check(app_configs=self.apps.get_app_configs()), [expected_error])

        class MultiClashModel(models.Model):
            # Two related fields with attname 'rel1_id' and 'rel2_id'
            rel1 = models.ForeignKey('self', on_delete=models.CASCADE)
            rel2 = models.ForeignKey('self', on_delete=models.CASCADE)
            # Properties 'rel1_id' and 'rel2_id' clash with both related fields
            @property
            def rel1_id(self):
                return 1
            @property
            def rel2_id(self):
                return 2

            class Meta:
                app_label = 'check_framework'

        expected_errors = [
            checks.Error(
                "The property 'rel1_id' clashes with a related field accessor.",
                obj=MultiClashModel,
                id='models.E025',
            ),
            checks.Error(
                "The property 'rel2_id' clashes with a related field accessor.",
                obj=MultiClashModel,
                id='models.E025',
            ),
        ]
        self.assertEqual(MultiClashModel.check(app_configs=self.apps.get_app_configs()), expected_errors)

        class NoClashModel(models.Model):
            # Related field 'rel' with attname 'rel_id'
            rel = models.ForeignKey('self', on_delete=models.CASCADE)
            # Property 'other_prop' does not clash with any related field's attname
            @property
            def other_prop(self):
                return 1

            class Meta:
                app_label = 'check_framework'

        self.assertEqual(NoClashModel.check(app_configs=self.apps.get_app_configs()), [])

        class PartialClashModel(models.Model):
            # Related fields 'rel1' and 'rel2' with attname 'rel1_id' and 'rel2_id'
            rel1 = models.ForeignKey('self', on_delete=models.CASCADE)
            rel2 = models.ForeignKey('self', on_delete=models.CASCADE)
            # Property 'rel1_id' clashes, 'rel2_id' does not
            @property
            def rel1_id(self):
                return 1

            class Meta:
                app_label = 'check_framework'

        expected_error = checks.Error(
            "The property 'rel1_id' clashes with a related field accessor.",
            obj=PartialClashModel,
            id='models.E025',
        )
        self.assertEqual(PartialClashModel.check(app_configs=self.apps.get_app_configs()), [expected_error])

        class NoRelatedFieldsModel(models.Model):
            # No related fields, so no accessors to clash with properties
            @property
            def prop(self):
                return 1

            class Meta:
                app_label = 'check_framework'

        self.assertEqual(NoRelatedFieldsModel.check(app_configs=self.apps.get_app_configs()), [])
