class ModelFormMetaclassTests(TestCase):
    def test_base_formfield_callback_used(self):
        # Test Path 1 and 2: bases have Meta.formfield_callback
        # Define a mock callback
        called_with = []

        def callback(*args, **kwargs):
            called_with.append(True)
            return Field(**kwargs)

        class ParentForm(metaclass=ModelFormMetaclass):
            class Meta:
                formfield_callback = callback

        # ChildForm's metaclass should inherit this
        class ChildForm(ParentForm):
            pass

        # Now, create a model form to trigger processing
        class TestModel(models.Model):
            name = models.CharField(max_length=100)
            class Meta:
                app_label = 'tests'

        class TestForm(ChildForm):
            class Meta:
                model = TestModel
                fields = '__all__'

        # Instantiating the form should use the callback
        TestForm()
        self.assertTrue(called_with, "formfield_callback from parent's Meta was not used")

    def test_bases_order(self):
        # Test Path 2: first base doesn't have Meta.formfield_callback, second does
        called = []

        def callback1(*args, **kwargs):
            called.append(1)
            return Field(**kwargs)

        def callback2(*args, **kwargs):
            called.append(2)
            return Field(**kwargs)

        class ParentNoCallback:
            pass

        class ParentWithCallback:
            class Meta:
                formfield_callback = callback2

        class ParentWithCallbackFirst:
            class Meta:
                formfield_callback = callback1

        # ChildForm1: bases are ParentNoCallback, ParentWithCallback
        class ChildForm1(ParentNoCallback, ParentWithCallback, metaclass=ModelFormMetaclass):
            pass

        class TestForm1(ChildForm1):
            class Meta:
                model = ChoiceModel
                fields = '__all__'

        TestForm1()
        self.assertEqual(called, [2], "Second base's callback should be used")

        # ChildForm2: bases are ParentWithCallbackFirst, ParentWithCallback
        called = []
        class ChildForm2(ParentWithCallbackFirst, ParentWithCallback, metaclass=ModelFormMetaclass):
            pass

        class TestForm2(ChildForm2):
            class Meta:
                model = ChoiceModel
                fields = '__all__'

        TestForm2()
        self.assertEqual(called, [1], "First base's callback should be used")

    def test_no_bases_with_callback(self):
        # Test Path 3 and 4: no bases have Meta.formfield_callback
        class TestForm(metaclass=ModelFormMetaclass):
            pass

        # Test that _meta exists and formfield_callback is None
        self.assertTrue(hasattr(TestForm, '_meta'))
        self.assertIsNone(TestForm._meta.formfield_callback)

    def test_formfield_callback_in_class_attrs(self):
        # Test that formfield_callback in the class's attributes overrides base's Meta
        called = []

        def callback1(*args, **kwargs):
            called.append(1)
            return Field(**kwargs)

        def callback2(*args, **kwargs):
            called.append(2)
            return Field(**kwargs)

        class ParentForm(metaclass=ModelFormMetaclass):
            class Meta:
                formfield_callback = callback1

        class ChildForm(ParentForm):
            formfield_callback = callback2

            class Meta:
                model = ChoiceModel
                fields = '__all__'

        # Instantiating should use callback2
        ChildForm()
        self.assertEqual(called, [2], "formfield_callback in class attrs should override parent's Meta")

    def test_bases_is_basemodel_form(self):
        # Test Path 1: bases == (BaseModelForm,)
        from django.forms.models import BaseModelForm
        # Create a class with bases == (BaseModelForm,)
        class TestForm(metaclass=ModelFormMetaclass):
            __module__ = 'tests'

        self.assertEqual(TestForm.__bases__, (BaseModelForm,))
        # The metaclass should return early
        self.assertFalse(hasattr(TestForm, '_meta'), "Should return early when bases == (BaseModelForm,)")

    def test_model_form_instantiation(self):
