            Country.objects.values_list('name', flat=True, named=True)

    def test_flat_with_multiple_fields_raise_error(self):
        with self.assertRaisesMessage(TypeError, "'flat' is not valid when values_list is called with more than one field."):
            Country.objects.values_list('name', 'iso_two_letter', flat=True)

    def test_expression_field_ids(self):
        from django.db.models import F

        qs = Country.objects.values_list(F('iso_two_letter'), F('iso_two_letter'))
        self.assertEqual(list(qs), [('TC', 'TC')])

    def test_named_values_list_returns_namedtuples(self):
        qs = Country.objects.values_list('name', 'iso_two_letter', named=True)
        result = qs.get()
        self.assertEqual(result.name, 'Test Country')
        self.assertEqual(result.iso_two_letter, 'TC')

    def test_values_list_with_expression_and_regular_field(self):
        from django.db.models.functions import Upper

        qs = Country.objects.values_list('iso_two_letter', Upper('name'))
        self.assertEqual(list(qs), [('TC', 'TEST COUNTRY')])

    def test_flat_returns_flattened(self):
        self.assertEqual(
            list(Country.objects.values_list('iso_two_letter', flat=True)),
            ['TC']
        )

    def test_duplicate_expression_field_names(self):
        from django.db.models import F

        # Test that duplicate expressions generate unique field IDs
        qs = Country.objects.values_list(F('name'), F('name'))
        self.assertEqual(list(qs), [('Test Country', 'Test Country')])
