def test_init_subclass_with_auto_wrap():
    """Test that methods are wrapped correctly when auto_wrap_output_keys is set."""
    pd = pytest.importorskip("pandas")
    import numpy as np

    # Test case 1: auto_wrap_output_keys=('transform'), class defines transform and fit_transform
    class Estimator(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
        def transform(self, X):
            return X

        def fit_transform(self, X):
            return X

        def get_feature_names_out(self, input_features=None):
            return np.array(["x"])

    # Check set_output is available and wrapping works
    est = Estimator().set_output(transform="pandas")
    X_np = np.array([[1, 2], [3, 4]])
    assert isinstance(est.transform(X_np), pd.DataFrame)
    assert isinstance(est.fit_transform(X_np), pd.DataFrame)

    # Test case 2: method not in __dict__ but inherited and wrapped in parent
    class Parent(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
        def transform(self, X):
            return X

        def get_feature_names_out(self, input_features=None):
            return np.array(["x"])

    class Child(Parent):
        pass

    # Parent's transform is wrapped, Child inherits it
    child = Child().set_output(transform="pandas")
    assert isinstance(child.transform(X_np), pd.DataFrame)

    # Test case 3: only fit_transform is defined and wrapped
    class OnlyFitTransform(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
        def fit_transform(self, X):
            return X

        def get_feature_names_out(self, input_features=None):
            return np.array(["x"])

    est = OnlyFitTransform().set_output(transform="pandas")
    assert isinstance(est.fit_transform(X_np), pd.DataFrame)

    # Test case 4: auto_wrap_output_keys is empty, methods not wrapped
    class NoWrapEstimator(_SetOutputMixin, auto_wrap_output_keys=()):
        def transform(self, X):
            return X

    assert not hasattr(NoWrapEstimator(), "set_output")
