def test_get_col_items():
    from xarray.core.variable import IndexVariable

    # Mock class to simulate variables with different properties
    class MockVar:
        def __init__(self, is_index_var, level_names):
            self.is_index_var = is_index_var
            self._level_names = level_names

        def to_index_variable(self):
            class MockIndexVar:
                def __init__(self, level_names):
                    self.level_names = level_names

            return MockIndexVar(self._level_names)

    # Create a mapping with various cases:
    # - 'a': IndexVariable with level names
    # - 'b': IndexVariable without level names
    # - 'c': Non-IndexVariable
    mapping = {
        "a": MockVar(is_index_var=True, level_names=["a1", "a2"]),
        "b": MockVar(is_index_var=True, level_names=None),
        "c": MockVar(is_index_var=False, level_names=None),
    }

    # Patch isinstance to handle mock objects as IndexVariable where needed
    orig_isinstance = isinstance

    def mock_isinstance(obj, cls):
        if isinstance(obj, MockVar) and obj.is_index_var and cls == IndexVariable:
            return True
        if isinstance(obj, MockVar):
            obj = obj.to_index_variable()
        return orig_isinstance(obj, cls)

    with mock.patch("builtins.isinstance", side_effect=mock_isinstance):
        col_items = formatting._get_col_items(mapping)

    expected = ["a", "a1", "a2", "b", "c"]
    assert col_items == expected
