            _contains_subclass(
                'django.db.models.Model',
                ['invalid.module.path', 'django.contrib.auth.models.User']
            )
        )
        # All candidates raise ImportError
        self.assertFalse(
            _contains_subclass(
                'django.db.models.Model',
                ['invalid.module.path1', 'invalid.module.path2']
            )
        )
        # ImportError in first, no subclass in second
        self.assertFalse(
            _contains_subclass(
                'django.db.models.Model',
                ['invalid.module.path', 'django.db.models.Field']
            )
        )
