def test_exec_constructor_postprocessors():
    # Test case where an argument's class has postprocessors for the current class
    class ArgClass(Basic):
        pass

    class TestClass(Basic):
        pass

    # Define postprocessor functions
    def postproc1(obj):
        # Append 1 to args
        return obj.func(*(list(obj.args) + [1]))

    def postproc2(obj):
        # Prepend 2 to args
        return obj.func(*([2] + list(obj.args)))

    # Register in the mapping
    Basic._constructor_postprocessor_mapping[ArgClass] = {
        'TestClass': [postproc1, postproc2]
    }

    # Create instance
    arg = ArgClass()
    test_obj = TestClass(arg)

    # Execute
    result = TestClass._exec_constructor_postprocessors(test_obj)

    # Check result
    assert result.args == (2, arg, 1)

    # Clean up
    del Basic._constructor_postprocessor_mapping[ArgClass]

    # Test case with no postprocessors from arguments but some for the class itself
    class SelfClass(Basic):
        pass

    def postproc_self(obj):
        return obj.func(*(list(obj.args) + [5]))

    Basic._constructor_postprocessor_mapping[SelfClass] = {
        'SelfClass': [postproc_self]
    }

    self_obj = SelfClass()
    result_self = SelfClass._exec_constructor_postprocessors(self_obj)
    assert result_self.args == (5, )

    # Clean up
    del Basic._constructor_postprocessor_mapping[SelfClass]

    # Test case with multiple arguments and multiple postprocessors
    class ArgClass1(Basic):
        pass

    class ArgClass2(Basic):
        pass

    def postproc3(obj):
        return obj.func(*(list(obj.args) + [3]))

    def postproc4(obj):
        return obj.func(*(list(obj.args) + [4]))

    # Update mapping
    Basic._constructor_postprocessor_mapping[ArgClass1] = {
        'EmptyClass': [postproc3]
    }
    Basic._constructor_postprocessor_mapping[ArgClass2] = {
        'EmptyClass': [postproc4]
    }

    class EmptyClass(Basic):
        pass

    # Instance with two arguments
    a1 = ArgClass1()
    a2 = ArgClass2()
    test_obj2 = EmptyClass(a1, a2)

    result2 = EmptyClass._exec_constructor_postprocessors(test_obj2)

    # postproc3 and postproc4 are added in order of arguments processing
    # first a1's postprocs, then a2's. Applied in order postproc3 then postproc4
    # args start as (a1, a2), then append 3, then append 4
    assert result2.args == (a1, a2, 3, 4)

    # Clean up
    del Basic._constructor_postprocessor_mapping[ArgClass1]
    del Basic._constructor_postprocessor_mapping[ArgClass2]

    # Test no postprocessors at all
    class NoPostprocClass(Basic):
        pass

    npc_obj = NoPostprocClass()
    result_npc = NoPostprocClass._exec_constructor_postprocessors(npc_obj)
    assert result_npc is npc_obj
